mapper.select:
select eipd.id, eipd.contract_code, coalesce (eipd.contract_name,ec.contract_name ) contract_name, eipd.client_code client_code, eipd.client_name client_name , eipd.impairment_type , eipd.business_type , eipd.org_id , (select t.org_name from eg_org_company t where t.org_id = eipd.org_id limit 1) org_name, eipd.five_class , eipd.three_step , eipd.risk_exposure , eipd.provision_total , eipd.last_month_balance , eipd.this_month_provision , eipd.financial_institution , ec.contract_status , ec.financial_contract_status , eipd.voucher_id , eipd.account_date from eg_impairment_provision_detail eipd left join eg_contract_month ec on ec.contract_code =eipd.contract_code and ec.org_id =eipd.org_id and ec.del_flag ='0' where eipd.del_flag ='0'
and eipd.impairment_provision_id = #{queryDTO.impairmentProvisionId}
and eipd.contract_code like concat('%', #{queryDTO.contractCode}::text, '%')
and ec.client_name like concat('%', #{queryDTO.clientName}::text, '%')
and ec.org_id = #{queryDTO.orgId}
and ec.financial_contract_status in
#{item}
and ec.contract_status = #{queryDTO.contractStatus}
and eipd.business_type = #{queryDTO.businessType}
and eipd.five_class = #{queryDTO.fiveClass}
and eipd.three_step = #{queryDTO.threeStep}
and eipd.impairment_type = #{queryDTO.impairmentType}
and date_trunc('month', eipd.create_time) = date_trunc('month', #{queryDTO.impairmentCreateTime})
and eipd.id in
#{item}
order by eipd.id desc

select
sum(risk_exposure) as riskExposureSummary,
sum(provision_total) as provisionTotalSummary,
sum(last_month_balance) as lastMonthBalanceSummary,
sum(this_month_provision) as thisMonthProvisionSummary
from eg_impairment_provision_detail eipd
left join eg_contract_month ec on ec.contract_code =eipd.contract_code and ec.org_id =eipd.org_id and ec.del_flag ='0'
where eipd.del_flag ='0'

    and eipd.impairment_provision_id = #{queryDTO.impairmentProvisionId}


